alter table public.settings add column if not exists intro_epoch bigint not null default 0;
alter table public.guests add column if not exists album_published boolean not null default false;
create or replace function public.evening_admin(command text,guest_key uuid default null) returns void language plpgsql security definer set search_path='' as $$ begin if not public.is_organizer() then raise exception 'Только организатор' using errcode='42501'; end if; if command='intro' then update public.settings set intro_epoch=(extract(epoch from clock_timestamp())*1000)::bigint; elsif command='publish_all' then update public.settings set album_published=true; elsif command='publish_one' then if guest_key is null then raise exception 'Выберите гостя'; end if; update public.guests set album_published=true where id=guest_key; if not found then raise exception 'Гость не найден'; end if; elsif command='guest_delete' then if guest_key is null then raise exception 'Выберите гостя'; end if; delete from public.answers where guest_id=guest_key; delete from public.requests where guest_id=guest_key; delete from public.votes where guest_id=guest_key; delete from public.guests where id=guest_key; if not found then raise exception 'Гость не найден'; end if; else raise exception 'Неизвестное действие'; end if; insert into public.audit(actor,action) values(auth.uid(),'evening:'||command); end $$;
revoke all on function public.evening_admin(text,uuid) from public,anon;
grant execute on function public.evening_admin(text,uuid) to authenticated;
update storage.buckets set allowed_mime_types=array['image/webp','image/jpeg','image/png'] where id='event-photos';

do $x$ declare f text; begin select pg_get_functiondef('public.can_view_media(text)'::regprocedure) into f; execute replace(f,'s.album_published and','(s.album_published or g.album_published) and'); end $x$;
